cypress_script:
describe('Sortable Data Tables', () => {
  it('should display the sortable data tables', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('h1').should('contain', 'Data Tables');
    cy.get('#table1').should('be.visible');
    cy.get('#table2').should('be.visible');
  });
  it('should have action links for each row', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('#table1 a').should('have.length', 16);
    cy.get('#table1 a').contains('edit').should('be.visible');
    cy.get('#table1 a').contains('delete').should('be.visible');
  });
});

playwright_script:
test.describe('Sortable Data Tables', () => {
  test('should display the sortable data tables', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    await page.locator('h1').waitFor();
    await expect(page.locator('h1')).toHaveText('Data Tables');
    await expect(page.locator('#table1')).toBeVisible();
    await expect(page.locator('#table2')).toBeVisible();
  });
  test('should have action links for each row', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    const actionLinksCount = await page.locator('#table1 a').count();
    expect(actionLinksCount).toBe(16);
    await expect(page.locator('#table1 a:has-text("edit")')).toBeVisible();
    await expect(page.locator('#table1 a:has-text("delete")')).toBeVisible();
  });
});
